using NUnit.Framework;using UnityEngine;using CelestialMaker.Core;using BreakInfinity;
public class CoreTests {
 [Test]public void CampaignCompletionSurvivesUnitySerialization(){var sim=new Simulation(Data);sim.S.resets[2]=1;sim.S.time=1200;foreach(var u in ExpansionContent.Ascension)sim.Meta.ascensionUpgrades.Add(u.id);foreach(var u in ExpansionContent.Genesis)sim.Meta.genesisUpgrades.Add(u.id);foreach(var m in sim.Meta.megas)m.level=6;Assert.IsTrue(sim.CreateUniverse(1));Assert.IsTrue(sim.CreateUniverse(2));sim.Advance(0);Assert.IsTrue(sim.CampaignComplete);var copy=new Simulation(Data,JsonUtility.FromJson<State>(JsonUtility.ToJson(sim.S)));Assert.IsTrue(copy.CampaignComplete);Assert.AreEqual(1200,copy.Meta.campaignCompletedAt);}
 [Test]public void ExistingV2SaveWithoutCompletionTimestampLoads(){var sim=new Simulation(Data);sim.Meta.megas[0].level=2;sim.Meta.megas[0].building=true;sim.Meta.megas[0].work=98765;sim.S.prestige[0]=new BigDouble(19);var json=JsonUtility.ToJson(sim.S);json=System.Text.RegularExpressions.Regex.Replace(json,",?\"campaignCompletedAt\":[^,}]+","");Assert.IsFalse(json.Contains("campaignCompletedAt"));var copy=new Simulation(Data,SaveMigrations.Upgrade(JsonUtility.FromJson<State>(json)));Assert.AreEqual(2,copy.S.version);Assert.AreEqual(new BigDouble(19),copy.S.prestige[0].Value);Assert.AreEqual(98765,copy.Meta.megas[0].work);Assert.IsFalse(copy.CampaignComplete);Assert.AreEqual(0,copy.Meta.campaignCompletedAt);}
 Content Data=>JsonUtility.FromJson<Content>(Resources.Load<TextAsset>("content").text);
 [Test]public void LiveRemainderSurvivesSave(){var state=new State{liveRemaining=3.25};var copy=SaveMigrations.Upgrade(JsonUtility.FromJson<State>(JsonUtility.ToJson(state)));Assert.AreEqual(3.25,copy.liveRemaining);new Simulation(Data,copy);}
 [Test]public void HugeNumberSaveRange(){var n=new Number(BigDouble.Parse("1e10000"));var r=JsonUtility.FromJson<Number>(JsonUtility.ToJson(n));Assert.AreEqual(n.Value,r.Value);}
 [Test]public void DevelopmentMigration(){var old=new State{version=0};Assert.AreEqual(2,SaveMigrations.Upgrade(old).version);new Simulation(Data,old);}
 [Test]public void CurrencyCanNeverBeNegative(){var sim=new Simulation(Data);sim.Buy(0,long.MaxValue);sim.Advance(86400);foreach(var n in sim.S.resources)Assert.GreaterOrEqual(n.Value,BigDouble.Zero);}
 [Test]public void LifetimeRecordsGrossProduction(){var sim=new Simulation(Data);sim.S.owned[1]=10;sim.Advance(3600);Assert.Greater(sim.S.lifetime[0].Value,sim.S.resources[0].Value);}
 [Test]public void FreeTalentRespecCannotCreateCores(){var sim=new Simulation(Data);sim.S.resets[1]=1;sim.S.prestige[1]=new BigDouble(100);sim.Talent(Data.talents[0]);sim.Respec();sim.Respec();Assert.AreEqual(new BigDouble(100),sim.S.prestige[1].Value);}
 [Test]public void PremiumExcludedFromChallenge(){var a=new Simulation(Data);var b=new Simulation(Data);a.S.resets[0]=b.S.resets[0]=1;a.PremiumUntil=1000;a.EnterChallenge(0);b.EnterChallenge(0);a.Advance(100);b.Advance(100);Assert.AreEqual(a.S.resources[0].Value,b.S.resources[0].Value);}
 [Test]public void StoryPersistsAcrossPrestige(){var sim=new Simulation(Data);sim.Advance(200);Assert.IsTrue(sim.S.discoveredStories.Contains("s0"));sim.S.lifetime[0]=BigDouble.Parse("1e9");sim.Rebirth(0);Assert.IsTrue(sim.S.discoveredStories.Contains("s0"));}
 [Test]public void UniverseLawsChangeRules(){var sim=new Simulation(Data);sim.S.resets[2]=1;sim.SetLaw(0);var primary=sim.Flow(0);sim.Meta.lawReadyAt=0;sim.SetLaw(1);Assert.Greater(primary,sim.Flow(0));sim.Meta.lawReadyAt=0;sim.SetLaw(2);Assert.AreEqual(2,sim.S.universeLaw);}
 [Test]public void NullReportCannotInventZeroBeforeBalances(){var state=SaveMigrations.Upgrade(JsonUtility.FromJson<State>(JsonUtility.ToJson(new State())));Assert.IsNull(state.offlineReport);var sim=new Simulation(Data,state);sim.BeginOffline(3600);Assert.AreEqual(new BigDouble(10),state.offlineReport.before[0].Value);Assert.IsTrue(state.offlineReport.knownBefore[0]);}
 [Test]public void OfflineReportSurvivesUnitySerialization(){var sim=new Simulation(Data);sim.S.owned[1]=3;sim.BeginOffline(86400);sim.ProcessOffline(1);Assert.Greater(sim.S.offlineRemaining,0);var copy=SaveMigrations.Upgrade(JsonUtility.FromJson<State>(JsonUtility.ToJson(sim.S)));var restored=new Simulation(Data,copy);while(copy.offlineRemaining>0)restored.ProcessOffline();Assert.IsFalse(copy.offlineReport.active);Assert.AreEqual(86400,copy.offlineReport.processedSeconds,.01);Assert.Greater(copy.offlineReport.spent[0].Value,BigDouble.Zero);copy.offlineReport.dismissed=true;Assert.IsTrue(JsonUtility.FromJson<State>(JsonUtility.ToJson(copy)).offlineReport.dismissed);}
 [Test]public void ResonanceRequiresActiveSourceBranch(){var sim=new Simulation(Data);sim.S.resets[0]=1;sim.S.links[1]=0;var absent=sim.ProductionMultiplier(0);sim.S.owned[1]=1;sim.S.owned[4]=1;Assert.Greater(sim.ProductionMultiplier(0),absent);sim.S.paused[4]=true;Assert.AreEqual(absent,sim.ProductionMultiplier(0));}
 [Test]public void ResonanceDivertsActualInputLimitedOutput(){var sim=new Simulation(Data);sim.S.resets[0]=1;sim.S.owned[1]=1;sim.S.owned[4]=1;var before=sim.Flow(4);sim.Link(1,2);var after=sim.Flow(4);Assert.Greater(before,after);sim.S.paused[1]=true;Assert.AreEqual(BigDouble.One,sim.ProductionMultiplier(8)); }
 [Test]public void TalentDefinitionsDriveAllSpecializations(){var sim=new Simulation(Data);sim.S.resets[1]=1;sim.S.prestige[1]=new BigDouble(100);sim.Talent(Data.talents[8]);Assert.AreEqual(Data.talents[8].effect,sim.TalentMultiplier(1));sim.Talent(Data.talents[16]);Assert.AreEqual(Data.talents[16].effect,sim.TalentMultiplier(2));sim.S.resources[0]=new BigDouble(100000);Assert.IsTrue(sim.StartVoyage(0));Assert.AreEqual(Data.expeditions[0].duration/Data.talents[16].effect,sim.S.voyages[0].finish-sim.S.time,.0001);}
 [Test]public void PremiumRestoreUsesAbsoluteIntervals(){var sim=new Simulation(Data);sim.S.time=5000;sim.BoostWindows.Add(new BoostWindow{start=1000,end=2000});var expired=sim.Flow(0);sim.S.time=1500;Assert.AreEqual(sim.Flow(0),expired);sim.S.time=5000;Assert.AreEqual(expired,sim.Flow(0));}
}
